0091: async function request<T>(
0092:   path: string,
0093:   init: RequestInit & { accessToken?: string } = {}
0094: ) {
0095:   const headers = new Headers(init.headers);
0096: 
0097:   if (init.body && !headers.has('Content-Type')) {
0098:     headers.set('Content-Type', 'application/json');
0099:   }
0100: 
0101:   if (init.accessToken) {
