0106:     ...init,
0107:     headers,
0108:     credentials: 'include',
0109:   });
0110: 
0111:   if (!response.ok) {
0112:     let message = 'Request failed';
0113: 
0114:     try {
0115:       const errorBody = (await response.json()) as ErrorResponse;
0116:       message = errorBody.message || errorBody.detail || message;
0117:     } catch {}
0118: 
