8:
9:export interface VerifiedOpenfortSession {
10:  user: {
11:    id: string;
12:    email?: string | null;
13:    name?: string | null;
14:    phoneNumber?: string | null;
15:  };
16:  session: {
17:    id?: string | null;
18:    expiresAt?: string | null;
19:  };
20:}
21:
22:let cachedClient: Openfort | undefined;
23:
24:function getOpenfortClient() {
25:  if (cachedClient) return cachedClient;
26:
27:  const { openfort } = requireServerEnv(['openfort']);
28:  cachedClient = new Openfort(openfort.secretKey!, {
29:    basePath: openfort.baseUrl,
30:    publishableKey: openfort.publishableKey,
31:  });
32:
33:  return cachedClient;
34:}
35:
36:function normalizeOpenfortSession(session: unknown): VerifiedOpenfortSession {
37:  if (!session || typeof session !== 'object') {
38:    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
39:  }
40:
41:  const value = session as {
42:    user?: {
43:      id?: unknown;
44:      email?: unknown;
45:      name?: unknown;
46:      phoneNumber?: unknown;
47:    };
48:    session?: {
49:      id?: unknown;
50:      expiresAt?: unknown;
51:    };
52:  };
53:  const userId = value.user?.id;
54:
55:  if (typeof userId !== 'string' || !userId.trim()) {
56:    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
57:  }
58:
59:  return {
60:    user: {
61:      id: userId,
62:      email:
63:        typeof value.user?.email === 'string' ? value.user.email : undefined,
64:      name: typeof value.user?.name === 'string' ? value.user.name : undefined,
65:      phoneNumber:
66:        typeof value.user?.phoneNumber === 'string'
67:          ? value.user.phoneNumber
68:          : undefined,
69:    },
70:    session: {
71:      id: typeof value.session?.id === 'string' ? value.session.id : undefined,
72:      expiresAt:
73:        typeof value.session?.expiresAt === 'string'
74:          ? value.session.expiresAt
75:          : undefined,
76:    },
77:  };
78:}
