80:export async function verifyOpenfortAccessToken(accessToken: string) {
81:  try {
82:    const session = await getOpenfortClient().iam.getSession({ accessToken });
83:    return normalizeOpenfortSession(session);
84:  } catch (error) {
85:    if (error instanceof ApiError) throw error;
86:
